mapper.select:
SELECT question_type AS questionType,
       COUNT(DISTINCT question_id) AS wrongQuestionCount,
       COALESCE(SUM(wrong_count), 0) AS totalWrongTimes
FROM lp_wrong_record
WHERE student_id = #{studentId}
  AND is_deleted = 0

    AND class_id = #{classId}


    AND course_id = #{courseId}

GROUP BY question_type
ORDER BY totalWrongTimes DESC

SELECT wp.point_id AS pointId, COUNT(DISTINCT wr.question_id) AS wrongQuestionCount, COALESCE(SUM(wr.wrong_count), 0) AS totalWrongTimes FROM lp_wrong_record wr INNER JOIN lp_wrong_point wp ON wp.wrong_id = wr.wrong_id AND wp.is_deleted = 0 WHERE wr.student_id = #{studentId} AND wr.is_deleted = 0
AND wr.class_id = #{classId}
AND wr.course_id = #{courseId}
GROUP BY wp.point_id ORDER BY totalWrongTimes DESC
